func TestMatchWorkbooks(t *testing.T) {
	all := []exportWorkbook{
		{ID: "wb1", Name: "Finance Q3", Path: "/Finance/q3"},
		{ID: "wb2", Name: "Budget", Path: "/Finance/budget"},
		{ID: "wb3", Name: "Marketing Funnel", Path: "/Marketing/funnel"},
	}

	t.Run("query finance matches exactly the two finance workbooks", func(t *testing.T) {
		got := matchWorkbooks(all, "finance")
		if len(got) != 2 {
			t.Fatalf("expected 2 matches, got %d: %+v", len(got), got)
		}
		ids := map[string]bool{}
		for _, m := range got {
			ids[m.ID] = true
		}
		if !ids["wb1"] || !ids["wb2"] {
			t.Errorf("expected wb1+wb2, got %+v", got)
		}
		// Negative: marketing workbook excluded.
		if ids["wb3"] {
			t.Errorf("wb3 (Marketing) should not match 'finance'")
		}
	})

	t.Run("case insensitive", func(t *testing.T) {
		if len(matchWorkbooks(all, "MARKETING")) != 1 {
			t.Errorf("expected 1 case-insensitive match for MARKETING")
		}
	})

	t.Run("empty query matches nothing", func(t *testing.T) {
		if got := matchWorkbooks(all, "  "); len(got) != 0 {
			t.Errorf("expected 0 for empty query, got %+v", got)
		}
	})
}

func TestExportFormatBody(t *testing.T) {
	cases := []struct {
		format     string
		wantType   string
		wantLayout bool
	}{
		{"csv", "csv", false},
		{"xlsx", "xlsx", false},
		{"pdf", "pdf", true},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.format, func(t *testing.T) {
			t.Parallel()
			body := exportFormatBody(tc.format)
			f, ok := body["format"].(map[string]any)
			if !ok {
				t.Fatalf("format key missing/wrong type: %+v", body)
			}
			if f["type"] != tc.wantType {
				t.Errorf("type = %v, want %v", f["type"], tc.wantType)
			}
			_, hasLayout := f["layout"]
			if hasLayout != tc.wantLayout {
				t.Errorf("layout present = %v, want %v", hasLayout, tc.wantLayout)
			}
		})
	}
}

